def forward_diff(f, x, h):
    return (f(x + h) - f(x)) / h  # 오차 O(h)

def central_diff(f, x, h):
    return (f(x + h) - f(x - h)) / (2 * h)  # 오차 O(h²)

def richardson(f, x, h):
    # 간격 h, h/2 중심 차분 결합 → h² 항 소거, O(h⁴)
    d1 = central_diff(f, x, h)
    d2 = central_diff(f, x, h / 2)
    return (4 * d2 - d1) / 3

# f = sin, x = 1, h = 0.1 기준 오차
# 중심 차분 ≈ 9e-4, 리처드슨 ≈ 1e-7
# h를 너무 줄이면 반올림 오차 증가 (중심: h≈1e-5)
